 const assetNames=['cosmos','olive','dove','butterfly','faith-hands','open-book','journal','reflection-quill','prayer-envelope','faith-key','hope-nest','quiet-window','growth-vase','devotional-teacup','wisdom-scroll','grace-shell','anchor','bookmark','community','gratitude-basket','gratitude-bowl','hourglass','intention-heart','lantern','magnifier','milestone','purpose-compass','reflection','relationship-hands','reminder-bell','rest-stones','seedling','sunrise','wisdom-pearl'];
