 function render(){if(!active)return;points.clear();drag=null;pinch=null;panelDrag=null;guideX=guideY=false;const scroll=dialog.querySelector('.vs-scroll')?.scrollTop||0;resizeObserver?.disconnect();dialog.innerHTML=mainMarkup();canvas=dialog.querySelector('canvas');const surface=dialog.querySelector('.vs-canvas-surface');surface.addEventListener('pointerdown',pointerDown);surface.addEventListener('pointermove',pointerMove);surface.addEventListener('pointerup',pointerUp);surface.addEventListener('pointercancel',pointerUp);surface.addEventListener('keydown',keyMove);surface.addEventListener('click',e=>{if(e.detail!==0)return;const b=e.target.closest('[data-art-hit],[data-resize]');if(!b)return;if(b.dataset.artHit){selected=b.dataset.artHit;setPanel('peek');draw();}else if(selected){tab='illustrations';panel='edit';render();}});const grip=dialog.querySelector('.vs-grabber');grip.addEventListener('pointerdown',sheetDown);grip.addEventListener('pointermove',sheetMove);grip.addEventListener('pointerup',sheetUp);grip.addEventListener('pointercancel',sheetUp);dialog.querySelector('.vs-scroll').scrollTop=scroll;resizeObserver=new ResizeObserver(()=>{fitCanvas();sheetPosition();});resizeObserver.observe(dialog.querySelector('.vs-preview-mount'));resizeObserver.observe(dialog.querySelector('.vs-footer'));fitCanvas();sheetPosition();draw();}
