 function sheetPosition(){if(!active)return;const shell=dialog.querySelector('.vs-shell'),footer=dialog.querySelector('.vs-footer'),sheet=dialog.querySelector('.vs-drawer');shell.style.setProperty('--vs-footer-height',footer.getBoundingClientRect().height+'px');const offset=panel==='peek'?Math.max(0,sheet.getBoundingClientRect().height-104):0;sheet.style.setProperty('--vs-sheet-y',offset+'px');}
 function setPanel(next){panel=next;const sheet=dialog.querySelector('.vs-drawer'),grip=sheet.querySelector('.vs-grabber');sheet.classList.toggle('is-peek',panel==='peek');grip.setAttribute('aria-expanded',String(panel==='edit'));grip.setAttribute('aria-label',panel==='peek'?'Expand design tools':'Collapse design tools');grip.querySelector('span').textContent=panel==='peek'?'Swipe up for tools':'Slide down to arrange';sheet.querySelector('.vs-scroll').inert=panel==='peek';sheetPosition();}
 function sheetDown(e){if(busy)return;const sheet=dialog.querySelector('.vs-drawer'),max=Math.max(0,sheet.getBoundingClientRect().height-104);panelDrag={y:e.clientY,at:panel==='peek'?max:0,max,lastY:e.clientY,time:performance.now(),velocity:0,moved:false};sheet.classList.add('is-dragging');e.currentTarget.setPointerCapture(e.pointerId);}
 function sheetMove(e){if(!panelDrag)return;const now=performance.now(),dt=now-panelDrag.time;if(dt>0)panelDrag.velocity=(e.clientY-panelDrag.lastY)/dt;panelDrag.lastY=e.clientY;panelDrag.time=now;const dy=e.clientY-panelDrag.y;panelDrag.moved||=Math.abs(dy)>6;dialog.querySelector('.vs-drawer').style.setProperty('--vs-sheet-y',clamp(panelDrag.at+dy,0,panelDrag.max)+'px');e.preventDefault();}
