 for(const b of existing.values())b.remove();let handle=hits.querySelector('.vs-resize-handle');const r=artRects.find(r=>r.id===selected),art=draft.art.find(a=>a.id===selected);if(r&&art){if(!handle){handle=document.createElement('button');handle.className='vs-resize-handle';handle.dataset.resize='true';handle.setAttribute('aria-label','Resize and rotate selected illustration');handle.innerHTML=icon('resize');hits.append(handle);}const a=art.rotation*Math.PI/180,dx=r.w/2+5,dy=r.h/2+5;Object.assign(handle.style,{left:((r.x+dx*Math.cos(a)-dy*Math.sin(a))/f.w*100)+'%',top:((r.y+dx*Math.sin(a)+dy*Math.cos(a))/f.h*100)+'%'});}else handle?.remove();
