 function snapPosition(x,y){const f=FORMATS[draft.format],scale=canvas.getBoundingClientRect().width/f.w;guideX=Math.abs(x-.5)*f.w*scale<7;guideY=Math.abs(y-.5)*f.h*scale<7;return {x:clamp(guideX?.5:x,.07,.93),y:clamp(guideY?.5:y,.06,.94)};}
