 function pointerUp(e){if(!points.has(e.pointerId))return;points.delete(e.pointerId);pinch=null;if(points.size){const p=[...points.values()][0],art=currentArt();drag={id:art.id,start:p,art:clone(art),mode:'move'};}else{if(drag?.mode==='pending')selected=null;drag=null;guideX=guideY=false;if(tab==='illustrations')updateControls();}draw();}
 function keyMove(e){const target=e.target.closest('[data-art-hit]');if(target)selected=target.dataset.artHit;if(!selected||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Delete','Backspace'].includes(e.key))return;e.preventDefault();const art=draft.art.find(a=>a.id===selected);if(!art)return;if(['Delete','Backspace'].includes(e.key)){draft.art=draft.art.filter(a=>a.id!==selected);selected=null;}else{const delta=e.shiftKey?.04:.01;art.x=clamp(art.x+(e.key==='ArrowRight'?delta:e.key==='ArrowLeft'?-delta:0),.07,.93);art.y=clamp(art.y+(e.key==='ArrowDown'?delta:e.key==='ArrowUp'?-delta:0),.06,.94);}dirty=true;updateControls();draw();}
 async function persist(){const d=normalizeDesign(draft,kind);if(kind==='snapshot'&&!api.premium())d.watermark=true;localStorage.setItem(key(kind),JSON.stringify(d));dirty=false;if(kind==='widget')api.widgetSaved?.({...chosenVerse(),source:d.source,design:clone(d)});cleanPhotos();}
 async function exportPNG(share){if(busy)return;setPanel('peek');selected=null;syncArtUI();busy=true;const buttons=[...dialog.querySelectorAll('button,input,select')].map(el=>({el,disabled:el.disabled}));buttons.forEach(({el})=>el.disabled=true);message('Preparing your PNG…');try{const out=document.createElement('canvas');await drawTo(out,true);const blob=await new Promise((resolve,reject)=>out.toBlob(b=>b?resolve(b):reject(new Error('Could not create an image.')),'image/png'));const v=chosenVerse(),filename=`her-crown-${v.reference.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-${draft.format}.png`;const file=new File([blob],filename,{type:'image/png'});if(share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:v.reference});message('Snapshot shared.');}else{const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);const result=document.createElement('div');result.className='vs-export-result';result.innerHTML=`<img alt="Exported ${escape(v.reference)} snapshot"><a download="${filename}">Save PNG again ${icon('download')}</a>`;result.querySelector('img').src=out.toDataURL('image/png');result.querySelector('a').href=result.querySelector('img').src;dialog.querySelector('.vs-export-result')?.remove();dialog.querySelector('.vs-export-slot').replaceChildren(result);setPanel('peek');message('Your PNG is ready and your design is saved. Use Save PNG again if the download did not open.');}await persist();}catch(e){message(e.name==='AbortError'?'Sharing cancelled. Your design is still here.':'The image could not be exported. Your design is still here; please try again.');}finally{busy=false;buttons.forEach(({el,disabled})=>el.disabled=disabled);draw();}}
 async function upload(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){message('Choose a JPG, PNG, or WebP under 15 MB.');return;}if(busy)return;busy=true;const controls=[...dialog.querySelectorAll('button,input,select')].map(el=>({el,disabled:el.disabled}));controls.forEach(({el})=>el.disabled=true);message('Preparing your photo…');let url;try{url=URL.createObjectURL(file);const img=await image(url),scale=Math.min(1,1600/Math.max(img.width,img.height)),out=document.createElement('canvas');out.width=Math.round(img.width*scale);out.height=Math.round(img.height*scale);out.getContext('2d').drawImage(img,0,0,out.width,out.height);const blob=await new Promise(resolve=>out.toBlob(resolve,'image/jpeg',.88));if(!blob)throw Error();const id='photo-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);await media('put',id,blob);photo=await image(photoURL(blob));draft.photoId=id;draft.background='photo';draft.color='#FFFFFF';draft.photoShade=22;dirty=true;panel='peek';render();message('Photo ready. Adjust the shade or text color to suit it.');}catch{message('This photo could not be opened. Choose another image; your previous design is unchanged.');}finally{busy=false;controls.forEach(({el,disabled})=>el.disabled=disabled);if(url){URL.revokeObjectURL(url);images.delete(url);}}}
 function close(){resizeObserver?.disconnect();points.clear();drag=null;pinch=null;dialog.close();dialog.remove();active=false;confirmation=false;for(const url of photoURLs){URL.revokeObjectURL(url);images.delete(url);}photoURLs.clear();photo=null;cleanPhotos();api.closed?.(kind);}
 async function open(which,verse){if(active)return;kind=which;context={text:String(verse.text),reference:String(verse.reference),translation:String(verse.translation).toUpperCase()};draft=normalizeDesign(read(kind),kind);dirty=false;panel='peek';tab='background';selected=null;points.clear();pinch=null;drag=null;artRects=[];photo=null;confirmation=false;active=true;assets=assetNames;dialog=document.createElement('dialog');dialog.className='verse-studio';dialog.setAttribute('aria-labelledby','vs-title');document.body.append(dialog);render();dialog.showModal();dialog.addEventListener('cancel',e=>{e.preventDefault();if(panel==='edit')setPanel('peek');else requestClose()});dialog.addEventListener('click',handleClick);dialog.addEventListener('input',handleInput);dialog.addEventListener('change',handleChange);try{const response=await fetch('illustration-pack/manifest.json');const manifest=await response.json();const known=(manifest.assets||[]).map(a=>a.id||a.name).filter(a=>assetNames.includes(a));assets=[...new Set([...known,...assetNames])];}catch{}if(draft.photoId){try{const blob=await media('get',draft.photoId);if(!blob)throw Error();photo=await image(photoURL(blob));draw();}catch{message('Your saved photo is unavailable. Choose a replacement or a gradient.');draft.background='gradient';draft.photoId=null;dirty=true;draw();}}return dialog;}
 function requestClose(){if(busy||confirmation)return;if(!dirty){close();return;}if(confirmation)return;confirmation=true;const sheet=document.createElement('div');sheet.className='vs-confirm';sheet.setAttribute('role','alertdialog');sheet.setAttribute('aria-label','Keep your design changes?');sheet.innerHTML='<div><h2>Keep your changes?</h2><p>Save this design, or return to the last saved version.</p><button class="vs-primary" data-vs="save-close">Save & close</button><button class="vs-confirm-discard" data-vs="discard">Discard changes</button><button class="vs-text" data-vs="keep-editing">Keep editing</button></div>';dialog.querySelector('.vs-shell').inert=true;dialog.append(sheet);sheet.querySelector('button').focus();}
 async function handleClick(e){const b=e.target.closest('[data-vs]');if(!b||busy)return;const action=b.dataset.vs,value=b.dataset.value;if(action==='close'){requestClose();return;}if(action==='done'||action==='save-close'){try{await persist();close();}catch{message('Your design could not be saved. Free some browser storage and try again.');}return;}if(action==='discard'){close();return;}if(action==='keep-editing'){dialog.querySelector('.vs-confirm')?.remove();dialog.querySelector('.vs-shell').inert=false;confirmation=false;dialog.querySelector('[data-vs=close]').focus();return;}if(action==='toggle-panel'){if(performance.now()<panelClickUntil)return;setPanel(panel==='peek'?'edit':'peek');return;}if(action==='adjust-art'){tab='illustrations';panel='edit';render();return;}if(action==='tab'){tab=value;selected=null;panel='edit';render();dialog.querySelector('.vs-scroll').scrollTop=0;return;}if(action==='format'){draft.format=value;dirty=true;render();return;}if(action==='preset'){const p=PRESETS.find(p=>p.id===value);draft.colors=[...p.colors];draft.intensity=p.intensity;draft.third=p.third;draft.background='gradient';draft.color=value==='night'?'#FFFFFF':'#111111';dirty=true;render();return;}if(action==='third'){draft.third=!draft.third;dirty=true;render();return;}if(action==='upload'){dialog.querySelector('#vs-photo').click();return;}if(action==='remove-photo'){draft.background='gradient';draft.photoId=null;photo=null;dirty=true;render();return;}if(action==='ink'){draft.color=value;dirty=true;render();return;}if(action==='align'){draft.align=value;dirty=true;render();return;}if(action==='add-art'){if(draft.art.length>=6){message('You can add up to six illustrations. Remove one to make room.');return;}const id='art-'+Date.now();draft.art.push({id,asset:value,x:draft.art.length%2?.84:.16,y:draft.art.length%2?.82:.18,size:.23,rotation:0});selected=id;panel='peek';dirty=true;render();dialog.querySelector('.vs-scroll').scrollTop=0;return;}if(action==='select-art'){selected=value;panel='peek';render();dialog.querySelector('.vs-scroll').scrollTop=0;return;}if(action==='remove-art'){draft.art=draft.art.filter(a=>a.id!==selected);selected=null;dirty=true;render();return;}if(action==='reset'){draft=defaultDesign(kind);photo=null;selected=null;dirty=true;render();return;}if(action==='download'||action==='share'){await exportPNG(action==='share');return;}if(action==='save-widget'){try{await persist();message('Widget design saved. Add Her Crown from the widget gallery on your iPhone.');}catch{message('Your widget design could not be saved. Please try again.');}}}
 function handleInput(e){if(busy)return;const el=e.target;if(el.dataset.vsInput){const name=el.dataset.vsInput,value=Number(el.value);if(name.startsWith('art-')){const art=draft.art.find(a=>a.id===selected);if(!art)return;const prop=name.slice(4);art[prop]=['x','y','size'].includes(prop)?value/100:value;}else draft[name]=value;dirty=true;const output=dialog.querySelector(`[data-output="${name}"]`);if(output)output.textContent=value+(name==='angle'||name==='art-rotation'?'°':name==='fontSize'?'':'%');draw();}if(el.dataset.vsColor!==undefined){draft.colors[Number(el.dataset.vsColor)]=el.value;dirty=true;draw();}if(el.hasAttribute('data-vs-text-color')){draft.color=el.value;dirty=true;draw();}}
